using UnityEngine;using UnityEditor;using System;using System.IO;
public static class ValidateMowerInteraction {public static string Main(){GameObject floor=null,assembly=null,playerObject=null;int checks=0;void Check(bool ok,string msg){if(!ok)throw new Exception(msg);checks++;}try{
floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.localScale=new Vector3(30,1,30);assembly=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/Lawnmower/Driveable/Lawnmower_With_Trailer.prefab"),new Vector3(10000,.02f,10000),Quaternion.identity);var mower=assembly.GetComponentInChildren<LawnmowerController>();var bike=mower.GetComponent<BicycleController>();playerObject=new GameObject("Mower rider test");playerObject.SetActive(false);var cam=new GameObject("Camera").AddComponent<Camera>();cam.enabled=false;cam.transform.SetParent(playerObject.transform,false);cam.transform.localPosition=Vector3.up*1.2f;var cc=playerObject.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.3f;cc.center=Vector3.up*.9f;var player=playerObject.AddComponent<PlayerController>();player.characterCamera=cam;player.characterController=cc;player.enabled=false;var rider=playerObject.AddComponent<PlayerBicycleInteraction>();rider.player=player;playerObject.transform.position=mower.transform.position+Vector3.left*1.8f;playerObject.transform.rotation=Quaternion.Euler(0,90,0);playerObject.SetActive(true);Physics.SyncTransforms();rider.Tick(true);Check(rider.bicycle==bike,"Aiming selects mower");Check(rider.TryMount(),"Mount mower");Check(cam.transform.parent==bike.riderView&&!cc.enabled,"Camera and walking transfer");Check(mower.trailerJoint.GetComponent<Collider>()==null||mower.trailerJoint.GetComponent<Collider>().enabled,"Trailer still active");foreach(var w in mower.trailerWheels)Check(w.enabled,"Trailer suspension stays active while riding");var axle=bike.frontWheel.localPosition;for(int i=0;i<30;i++)rider.DriveRiding(0,1,true,true,.02f);mower.SendMessage("LateUpdate");Check(bike.CurrentSteeringAngle>20,"Steering works");Check(Vector3.Distance(axle,bike.frontWheel.localPosition)<.01f,"Front axle stays centered when steering");Check(!rider.IsBoosting,"No stamina boost on mower");Check(rider.TryDismount(),"Safe dismount");Check(cc.enabled&&cam.transform.parent==playerObject.transform,"Camera and walking restored");var result="PASS "+checks+" mower targeting/mounting/steering/dismount checks";File.WriteAllText("output/Lawnmower/interaction-validation.txt",result);return result;
}finally{if(playerObject){var interaction=playerObject.GetComponent<PlayerBicycleInteraction>();if(interaction&&interaction.IsRiding)interaction.TryDismount();}if(playerObject)UnityEngine.Object.DestroyImmediate(playerObject);if(assembly)UnityEngine.Object.DestroyImmediate(assembly);if(floor)UnityEngine.Object.DestroyImmediate(floor);}}}


